# -*- coding: utf-8 -*-
"""海德堡要理问答 52 主日：本站撰写的标题、精义、应用与交叉引用（均为转述，不是 CCI 原文）。
格式：n: (标题, 精义, 应用, bc列表, dort列表, 其他, 标记)  标记：K=重点 H=难点 ''=普通"""
HCD={
1:("唯一的安慰","整部要理问答的钥匙：我“不属于自己”，而属于救主。安慰有三重内容——罪债已被基督的血偿清；魔鬼的权势被打破；天父的护理保守。问2再列出认识安慰所需的三件事：罪与愁苦、得救、感恩——这就是全书的三部分。","凌晨不安时问自己：我是靠什么活着、靠什么死？把“我属于谁”放在“我能做什么”之前。",[13,26],["5.9"],"使徒信经末句“我信永生”","K"),
2:("从律法认识罪","认识愁苦的方法是律法：神的律法把要求总结为“爱神、爱人”（问4引太22）；而我们天生倾向恨神恨邻（问5）。律法是镜子，不是梯子。","读十诫不是为了自我评分，而是被带到基督面前；教导孩子时先说“神爱你”，再说“神的要求”。",[15,25],["3-4.5"],"","K"),
3:("人的败坏","神原本造人为善（问6），败坏源于始祖的堕落（问7），今天人“倾向于”恨神恨人（问8）；唯有重生才能行善。这一课与 BC 14–15 并读。","对人性不要太乐观或太悲观：既不否认人仍是神的形象，也不否认全面的败坏。",[14,15],["3-4.1","3-4.2","3-4.3"],"","H"),
4:("公义与怜悯","罪必受刑罚：神的公义不容许不了了之（问10），但他“也是慈爱的”（问11）——这里是转折：怜悯不能取消公义，而要通过满足公义来显明（下一课进入基督）。","“上帝是爱”不能用来取消“上帝是公义”；福音的好处恰在二者在基督里相遇。",[20],["1.1","2.1"],"","K"),
5:("需要中保","人无法偿还罪债（问13），受造物也不能替我们赎罪（问14）；因此需要一位“真人、无罪、同时又胜过一切受造物”的中保（问15–）。这是一个“排除法”：先说谁不能救，再说谁能救。","在自救的诱惑里（道德、宗教、成就）停下来：所有努力都落在“问13–14”这堵墙上。",[20,21],["2.1","2.2"],"","K"),
6:("真神又真人","中保必须是真人（义务由人偿还）且无罪，同时必须是真神（担得起神的忿怒并赢回义与生命）。问19说明这福音如何由伊甸园一路展开到基督。","遇到“耶稣只是好老师”的说法时，用问16–17回应：救赎需要的是中保，而不是教师。",[18,19],["2.4"],"尼西亚信经；亚他那修信经 29–37","K"),
7:("真信心与使徒信经","问20：基督不是自动救所有人，只救那“被真信心接在他里面”的人；问21定义真信心（知识＋确信）；问22–23引入使徒信经——它是“信仰的纲要”，由十二条分成三部分。","把“信”分成“相信什么”（知识）与“靠谁”（确信）：只有知识会冷，只有情感会浮。",[22,7],["3-4.14"],"使徒信经","K"),
8:("三位一体","问24把信经分为三部分：父与我们的创造、子与我们的救赎、圣灵与我们的成圣。问25：只有一位神，却有三位——这不是三个神。","每次祷告都在回应三一神：父的爱、子的恩、灵的同在，不必等懂完神学才开始亲近神。",[8,9],[],"亚他那修信经；尼西亚信经","H"),
9:("父神创造","“我信神，全能的父，创造天地的主”：这位创造主，藉着基督成了“我的神、我的父”（概述）。父与创造连在一起：信创造不是自然神学，而是儿女对天父的信靠。","当焦虑于“世界为什么这样”，先回到“他是我的天父”。",[12,13],[],"使徒信经第1条","K"),
10:("神的护理","护理是神藉着“全能、永在的能力”托住并管理万有，一草一木、雨旱丰荒、健康疾病，都“非出于偶然”（问27）；对信徒的益处是“逆境中忍耐，顺境中感恩，对将来信靠天父”（问28）。BC 13 同样讲护理的“安慰”。","受苦与顺利时各有一句话：忍耐，感恩；不把偶然、命运当作最后的话。",[13],[],"","K"),
11:("耶稣：救主","“耶稣”意为“救主”；谁到别处寻求救恩，就是拒绝这位独一救主（问30）。这是对当时天主教圣徒敬拜与一切自义的直接反驳。","检查“别处”：事业、关系、道德成就，是否悄悄成了我的“救主”。",[21],[],"","K"),
12:("基督与基督徒","“基督”意为受膏者——先知、祭司、君王三职（问31）；因我们属于他，也分享这三职：认信他的名、献上自己为活祭、以自由良心与罪魔争战（问32）。","“基督徒”是一个职分的名称：认信、献身、争战，这三件事落到周一的工作与家庭。",[21,26],[],"","K"),
13:("神的独生子，我们的主","基督是“独生子”，我们是“收纳的儿女”（问33）；他用血买赎我们，所以是“我们的主”（问34）。","亲近神的两个词并存：<b>儿女的勇气</b>与<b>仆人的顺服</b>。",[10,18],["1.7"],"使徒信经第2、3条","K"),
14:("成孕与降生","圣灵感孕、童贞女所生（问35）；益处：基督在我们的肉身里作中保，用自己的圣洁遮盖我们“与生俱来的罪”（问36）。","耶稣取了真实的人性——他懂我们的软弱；也因为无罪，他能代替我们。",[18,19],[],"使徒信经；尼西亚信经","H"),
15:("受难","基督一生都在承受神对全人类罪的忿怒（问37）；在彼拉多手下受审，是“无罪者被定罪，使我们脱离神严厉的审判”（问38）；钉十字架的死法意义特殊：他担当了“本该加在我身上的咒诅”（问39）。","面对愧疚：十字架不是“教育我们”，而是“替代我们”。",[20,21],["2.2","2.3"],"使徒信经","H"),
16:("死、埋葬与降在阴间","基督必须死（问40）；埋葬确证他真死（问41）；信徒的死不再是赔偿罪债，而是“脱离罪恶、进入永生的入口”（问42）；十字架的益处是治死旧人、感恩的献祭（问43）；<b>降在阴间</b>：问44解为基督受苦时（尤其在十字架上）所忍受的“无法言表的痛苦、疼痛、恐惧和苦楚”，使我们在极大的悲痛与试探中仍有安慰。","<b>难点：</b>“降在阴间”的解释在不同传统中不同；HC 采用“基督受苦”的读法（与 URCNA 在使徒信经页的注释一致），这是改革宗的典型读法。",[21],["2.4"],"使徒信经","H"),
17:("复活","复活带来三重益处：他胜过死，使我们在他的义上有份（问45）、使我们靠他的能力“复活”（重生）、成为我们荣耀复活的确据。","复活节不是“一年一度的好消息”，是每天“新生命”的来源。",[37],[],"使徒信经","K"),
18:("升天","基督升天后，其人性在天上，神性无处不在（问47–48）；升天的益处：他在天上为我们代求、我们的肉身在天上有“保证”、他差圣灵到我们中间（问49）。","“他不在这里”不等于“他不在场”：圣灵与圣道使天上的基督临到此地。",[19,26],[],"使徒信经","H"),
19:("坐在右边与再来","坐在“全能父神的右边”，是要彰显他是教会的头，父藉着他管理万有（问50）；益处：他把圣灵的恩赐赐给我们、用能力保护我们（问51）；他再来审判，对信徒是安慰，对仇敌是审判（问52）。","把“审判日”当作安慰而不是威吓：审判我们的，是那替我们受审的基督。",[26,37],[],"使徒信经","K"),
20:("圣灵","圣灵与父、子同为真神；他使我们与基督、与他的一切恩惠同在，并永远与我们同在（问53）。","每一次读经与祷告，都在圣灵的作为里；不要以“热闹”或“感觉”衡量他。",[11],["3-4.11","3-4.12"],"尼西亚信经第三条","K"),
21:("圣而公之教会","教会是神从起初到末了所召聚的会（问54）；圣徒相通：同领基督与他的恩赐，并彼此用恩赐服事（问55）；“罪得赦免”：我们的罪“再也不被记念”（问56）。","教会不是可选项：圣徒相通使我们必须彼此担当；也不要拿“自己的圣洁”衡量教会，教会是蒙赦免的人群。",[27,28,29],["5.3"],"使徒信经","K"),
22:("身体复活与永生","“身体复活”：我的灵魂一离开身体，就被接到基督那里；这身体也将复活（问57）；“永生”让我们现在就尝到永恒喜乐的开端（问58）。","对死亡有盼望，不是逃避现实，是在基督里“已开始”的永生。",[37],[],"使徒信经末两条","K"),
23:("唯独因信称义","这一课与新教改革的核心相连：称义“全是出于神的恩典”（问59–60）；信是接受基督的义的“工具”（问61）。","遇到焦虑：称义是“一次的宣告”，成圣是“一生的更新”，二者不能混淆也不能分开。",[22,23],["2.8"],"","H"),
24:("善行与称义","我们的善行因不完美，不能成为义（问62）；神仍应许赏赐，但是出于恩典（问63）；真信心“不能不结出感恩的果子”（问64）。","既不靠善行得救，也不因“因信称义”而放纵：果子是证据而不是代价。",[24],["5.12","5.13"],"","H"),
25:("圣言与圣礼","圣灵藉福音的宣讲“生出”信心，并藉圣礼“坚固”信心（问65–67）；新约只有两个圣礼：洗礼与圣餐（问68）。","圣礼是“看得见的话”：它们不增添，而是使应许更确定。",[33],["3-4.17"],"","K"),
26:("洗礼的意义","洗礼表明并印证：基督的宝血与圣灵洗净我们（问69–71）；其根据是神的应许（可16:16；太28:19 等）。","洗礼提醒的是“我已被洗净”，而非“我已完全”。",[34],[],"","K"),
27:("洗礼与婴孩","外在的水并不洗罪（问72），但洗礼“代表”基督的血与圣灵所成就的（问73）；婴孩应受洗，因他们与父母同属于圣约和教会（问74，用割礼作对照）。","<b>难点：</b>婴儿洗礼的根据是圣约，不是“水的功效”；父母要在家里实行信仰教导，见第六部分的圣约线索。",[34],["1.17"],"","H"),
28:("圣餐的意义","圣餐表明并印证基督的献祭于我们有益（问75）；“吃他的身体、喝他的血”是“信靠他的受苦与死”并被圣灵联于他（问76）。","每一次圣餐都是“向后看（他死了），向上看（他在天上），向前看（婚筵）”。",[35],[],"","K"),
29:("饼与杯：与天主教、路德宗的分野","问78：饼与酒并非真的变成基督的身体与血；问79：称饼为基督的身体，是“圣礼性的称呼”，用来保证我们真的与他同在。","<b>难点：</b>问78直接否认饼酒“变成”基督的身体与血，问79–80讲明圣礼性的称呼与“在天上”的基督；16世纪德国领地里还有与路德宗关于基督身体如何同在的争论（本站的史背景解读，约）。改革宗的落脚点是：圣灵在信心中使我们与天上的基督相交（问76）。",[35],[],"","H"),
30:("圣餐与弥撒；入席与否","问80把圣餐与弥撒区别开来：弥撒贬低基督一次的献祭；问81–82：为谁设席？对罪忧伤、信靠基督的人；那些言行显为不信不虔者不可领。","圣餐桌同时是<b>邀请</b>与<b>界限</b>：对软弱的信徒邀请，对不悔的人设限。",[35],[],"","H"),
31:("天国的钥匙","天国的钥匙有二：福音的宣讲与教会纪律（问83–85）。福音宣告“凡信的都得赦免”，纪律对公开不悔改者“闭”天国的门。","教会纪律的目的是挽回，不是惩罚；一个不纪律的教会也不真爱人。",[29,32],[],"","H"),
32:("感恩的必要","第三部开始：既然我们“不是靠自己的功德”得救，为何还要行善？因为基督救我们，也更新我们——善行是果子（问86–87）。","感恩不是“补偿”，而是自由的“回应”。",[24],["5.12"],"","K"),
33:("悔改：旧人死、新人生","真正的悔改（问88）包含旧人死去（问89）和新人活出（问90），“善行”的标准是：出于真信心、合乎神的律法、为荣耀神（问91）。","悔改不是情绪，而是“转离罪，归向神”的方向性生活。",[24],["5.4"],"","K"),
34:("律法与第一条诫命","十诫由神亲自颁布（问92）；分为两块板（问93）；第一条：唯独敬拜耶和华，不可有别的神（问94–95）。","每一条诫命背后都是“我是耶和华你的神”这一个“开场白”：律法在恩典的框架内。",[25],[],"","K"),
35:("第二条：敬拜的方式","神不愿被形像所代表（问96–97）；教会也不可用像来教导会众（问98）。","“怎样敬拜”不由我们的创意或感觉决定，而是由神的话规定（BC 7 的“圣经详细记述了神要我们以怎样的方式敬拜他”）。",[7],[],"","H"),
36:("第三条：神的名","不可亵渎神的名（问99–100）。","言语里的敬畏：从口头禅到发誓。",[],[],"","K"),
37:("敬虔的起誓","在官府要求与公义的情形下，可以指着神的名起誓（问101）；不可指着圣徒或受造物起誓（问102）。","重要承诺前，想到“神在听”：真诚比形式更重要。",[36],[],"","K"),
38:("第四条：安息日","问103：安息日的核心是福音的宣讲与学校（办学）、圣礼、公祷、周济；并要“一生”不做恶事，使神在我里面做工，开始尝到“永恒的安息”。","<b>难点：</b>在欧陆改革宗里，这条诫命的“主日如何守”常与威斯敏斯特的“基督徒安息日”表述比较，见第六部分。",[],[],"","H"),
39:("第五条：权威","爱戴、尊敬与顺服父母及一切在上掌权者（问104）；BC 36 讲官府的职分。","尊重权威不等于盲从：HC 的前提是“神的话”。",[36],[],"","K"),
40:("第六条：生命","不可杀人；不止是杀害，还包括怨恨、嫉妒、愤怒（问105–107）；积极面：爱邻舍。","暴力从心里开始，爱也从心里开始。",[],[],"","K"),
41:("第七条：婚姻与贞洁","禁止一切不洁的行为、言语、思想；婚姻内外都当贞洁（问108–109）。","在文化压力下，婚姻与单身都是一种忠心的方式。",[],[],"","K"),
42:("第八条：财物","禁止偷窃与一切邪恶的手段（问110）；积极面：帮助邻舍、为生计勤勉工作、周济贫困（问111）。","职场、金钱、慷慨：HC 要求的是整全的诚实。",[],[],"","K"),
43:("第九条：真理","不可作假见证；要爱真理，诚实地说话（问112）。","真话与爱同在：“用爱心说诚实话”。",[],[],"","K"),
44:("第十条与十诫的不完美","第十条：不可贪心（问113）；今生没有人能完全守住（问114）；仍要严肃教导十诫，是为了使我们渴望更新（问115）。","律法在新生命里有“督导”作用，而不是“定罪”作用。",[25],["5.1","5.2"],"","H"),
45:("祷告的必要","祷告是感恩的“主要部分”（问116）；蒙垂听的祷告五要素（问117）；主祷文是基督亲自所教（问118–119）。","祷告不是“说服神”，而是“向天父报告与托付”。",[26],[],"","K"),
46:("称呼：我们在天上的父","“我们的父”教我们像孩子一样信靠，并为他人祷告（问120）；“在天上”提醒神的威严与大能（问121）。","每次开口“我们”，都在拆掉个人主义。",[],[],"","K"),
47:("第一个祈求：愿人都尊你的名为圣","求神使我们真认识他、称颂他的一切作为（问122）。","目标不是“我的满足”，而是“神的荣耀”。",[],[],"","K"),
48:("第二个祈求：愿你的国降临","神的国藉着圣灵与圣道成长；求教会兴旺、撒但的国倾覆（问123）。","为福音和宣教祷告，也为我自己的顺服。",[27],[],"","K"),
49:("第三个祈求：愿你的旨意成就","求神使我们舍己，欢喜顺服他的旨意；天使在天上如何顺服，我们在地上也如何（问124）。","把“你的旨意成就”当作信靠，不是认命。",[13],[],"","K"),
50:("第四个祈求：日用的饮食","求神供给身体的一切需要，也使我们知道一切美物都来自他（问125）。","日常的饮食里认出神的手。",[13],[],"","K"),
51:("第五个祈求：免我们的债","求神因基督的血免我们的债；我们也“从心里饶恕”别人（问126）。","饶恕是“已被饶恕者”的新习惯。",[23],[],"","K"),
52:("第六个祈求与结尾","“不叫我们遇见试探”：求保守，使我们不被撒但、世界、肉体胜过（问127）；结尾荣耀颂（问128）；“阿们”意味着“确实是这样，祷告被垂听”（问129）。","以“阿们”结束全书：信靠，是对“神一定垂听”的确信。",[26],["5.7","5.8"],"","K"),
}

# ---- 引号纪律：只有与 CCI 文本逐字一致的片段才保留“ ”；其余作为本站转述，去掉引号 ----
import re as _re, json as _json
def _nm(s): return _re.sub(r'[\s，。；：、！？“”‘’「」『』"\'（）()…—–·,.;:]|⟦\d+⟧','',s)
def _corpus():
    c=""
    for q,(a,b) in __import__("quotes").HC.items(): c+=a+b
    for v in _json.load(open("data/ib_summ.json",encoding="utf-8")).values(): c+=" ".join(v) if isinstance(v,list) else str(v)
    return _nm(c)
_C=_corpus()
def _fix(s):
    if not isinstance(s,str): return s
    def f(m):
        x=m.group(1)
        parts=[p for p in _re.split(r'……|…',x) if len(_nm(p))>=4]
        return m.group(0) if (parts and all(_nm(p) in _C for p in parts)) or len(_nm(x))<4 else x
    return _re.sub(r'“([^”]+)”',f,s)
HCD={n:tuple(_fix(x) if i in (1,2,5) else x for i,x in enumerate(v)) for n,v in HCD.items()}

